) AS (
  VALUES 
    (181::BIGINT, 'Las clases son una tremenda mierda, pero es muy fácil faltar porque el mae justifica muy fácilmente. Si quiere matricular esto por relleno o por cumplir con la deportiva, hágalo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-04T00:00:00+00:00'::TIMESTAMPTZ, '7e5ff7426c231264e8d52b39e4bc0368b54aee0755d89083b03d7f9e92a670b8'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'El profe es una teja como persona y como atleta. Se pasa fácil, solo ir a las clases y participar en los torneos internos. Si usted es una persona medianamente atlética no lo va a sentir cansado, de igual manera, si usted no es una persona muy activa, no va a ser matado, el profe no exige mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'ffe0af75ae68fddfe8df0431530673ec5b06ff2fe8e2ccb1ca1deff2688c19ff'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Súper buena nota. Las clases siempre son diferentes y se mejora bastante la condición física.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '78a830598761b9ac986fa9c37ad0ccfceb1e26a293a02c29d4a1f27da1057448'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Muy buen profe, buena gente, son clases entretenidas y sí se gana condición física.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '42fd73de5037c3b274641008026e4f096b8f99151f9725c9ddb9e26f987c01a6'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Excelente persona y profesor. Sus clases si son cansadas pero se gana resistencia, además, si falta a alguna clase o le falta algo de calificación él hará lo posible para ver cómo reponerlo. El mejor profe de deportiva.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, '2c749d1869ec0e1b7f0de41a9c8621608665d9a89e4a114ad012b5c00d270c0a'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Muy buen profe, cada dinámica deportiva es muy chiva y no exige mucho para pasar, la clase es un buen des-estrés de todas las demás materias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '10e0f01be4cf0282b2f08af4980fc2fcdd5433d781b3d846dd378548e03375d6'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Excelente profe, no sobreexige a los estudiantes sino que los entiende, solo vaya y participe, le va a terminar gustando y pasa comodamente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '42c613c06a80e0eb55edee0d28eb52cc34437c3b8d432d7523fbe480ec2405d6'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Un profe muy buena nota, llevaria con el de nuevo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd9ef761860cb4ab858db9083f6aff9e23fa89bc4adf1445665ee2d2039b39f6f'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Una teja de profe, muy amable con sus estudiantes. El curso es un toque cansado, pero es divertido. Si falta puede reponer lecciones en las últimas semanas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'f477971e2542dba67f8977448379401a4b57ae9321966bb0c027e72f64bcdd10'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'El curso es muy cansado, pero se gana resistencia, Solamente nos faltes a clases ni a las actividades extras como el "Campo Traviesa" y el "Torneo de Atletismo" y pasas con 10. Permite reponer las clases a partir de semana 10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '9e865f65bbc2e1f9dba1de7cea10387d9895db2e4eab4b0e5f5c2ad45b43cf7e'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'El profe lo único que pide es que uno participe en clase, es compresivo si uno se siente mal durante una clase pero si toma en cuenta si uno falta y no presenta algún comprobante, en general lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e6cb6096e9bafc9df3b57ce115548e7b83a97da918ff26c8ab107fca0dc85b09'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Super buena gente el profe, las clases son muy divertidas. No pide casi nada, solo con ir y participar se pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'ad2628ac949597555d12869a0c84e670ae897ec24b13b84796a9a2f525cf7aa5'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Es un curso para hacer deporte y eso se agradece. Olvídese de teoría y trabajos adicionales, lo más que debe hacer es una infografía súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'd102c01a64fa6f38aa6f046858ac3cc7e7821c14286cda8a1c6096e94040a891'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'El profe es una teja, super comprensivo con los estudiantes y se preocupa por que su clase sea un momento de liberación de estrés del semestre. Se nota que ama lo que hace.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'db2f6c88a72fd303f9b94fe73e6d505b56c55b6d7585ed6d6f2ee7ef2bd154ce'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Super buen profe, solamente con conectarse a las clases, prender cámara y hacer la media hora de ejercicio se gana el curso. La ultimas dos/tres semanas no dio clases para que tuvieramos chance de hacer proyectos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-15T00:00:00+00:00'::TIMESTAMPTZ, '271892453758a490760d6dbe9f068498021dad4bead980a34db1a9a069e6c439'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Si les encanta el futbol, este curso les sentara bien, se nota que al profe le apasiona lo que hace, los trabajos son super fáciles, en menos de 30 minutos se hacen, brinda ayuda de ser necesario, excelente persona, lastima llevarlo virtual.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Da crédito extra']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '417b748fb087b3ea869ee9dc1afccdde6cade07a9e46de0041d20d5ee6a4840e'::TEXT, ARRAY[585]::BIGINT[]),
    (181::BIGINT, 'Excelente profe, demasiado buena persona, muy cómico y empático con los estudiantes, ayuda mucho, sus ejercicios son muy buenos y se disfruta la clase. Tiene muchísima vocación, no dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'fcd55e254d5a5ca12feb6cba2afea3ea47e11788bc2c83b53f417ff0eba7a539'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'El mejor profe del mundo, matricule con el sin miedo. 100 % recomendado. Las clases son muy entretenidas y hay que activar la cámara. Si usted no se puede conectar, nada más manda evidencias que si hizo la rutina de esa semana.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4d71d9a80dae872c04b24355f33498ff00023a6d24b6c16b9dbbe56d08164078'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Es un excelente profesor, si enciende la cámara y hace las actividades durante la clase, tiene todo el puntaje, aunque haga mal los ejercicios. Si no puede encender la camara solo se toma unas haciendo ejercicio y listo el proyecto es una imagen con una rutina super facil 20/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '231526184730d05d54cee253d34f4f8178f90e7073a6776caae587fe8bb21c02'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'El profesor es muy bueno, las clases se tratan de hacer ejercicio con la cámara encendida, cosa que si usted tiene baja autoestima o ansiedad social no es muy bueno. Además de ello, deja una sola tarea la cual solamente explica en la clase y no deja ningún documento formal.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'de2a8340a3bc8d696a4437ea1c7d030b76cade6b800ab99cff6f6dc32e2acf78'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Súper excelente, se ve que sabe lo que hace. Las rutinas que desarrolló durante el semestre fueron bastante intensas y funcionales. En las clases lo anima a uno con música y con porras, y si no se puede realizar algún ejercicio o se siente muy agotado, el profe comprende. 11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'e4c15b6ff034320fddacc006365aa483d469b05084d519d099d7aa2c26e38f99'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Nos ponía a hacer una rutina en vivo por zoom con cámara encendida. Si uno no podía ir o no ponía cámara, tenía que tomar fotos y subirlas en un Word al TecDigital. Los ejercicios eran muy buenos y la clase se disfrutaba montones. Totalmente recomendado para que hagan ejercicio en casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'b647b0f0ceca797f8bf5602d925a34fac9848e3d5563f715105de057c1d68922'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Se preocupa x el estado de los estudiantes, recomendadísimo...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '0051085ab8f44cf223df8b7d666c18c2c079fa4f875679877b46fcc0d6bcfc51'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Super recomendado. Hace las clases muy interactivas y son divertidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '0e8fc05c5757f0a742abffdc4826b781c337f525799380f8dae4de490c1e53cf'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'El profe es demasiado pura vida y hace las clases muy dinámicas y divertidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'dd4b4e427433553fbca48cc132bd814a6cb87f472d5ebc4aeae15d4b35ceb69f'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Es súper linda persona. En presencial hacía las clases muy dinámicas y si te sientes mal entiende. En virtual hace rutinas distintas todas las semanas que no duran mas de 1 hora, no tienes que encender la cámara y si algun dia tienes que faltar el te ayuda a reponer la clase con otro grupo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'f2740a1e7a8709d5892ac91f1fff77011b29cf4991d2a52066893c326a7ef9e8'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd7d7832cf5ddbd9d355ab8a19307b0ad793a3d9224f5a2c7a66bbe3bfe317d30'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Es super fácil sacarse un 100, solo tiene que participar y no faltar, es una persona excelente y no le exige si usted se siente cansado, es el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a5828e098dcef8612477b4db12ca996b9d10348a3a0e454868a779d1137bf630'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'El curso es fácil y muy entretenido, no es tan cansado y solo hay que hacer 2 actividades para pasarlo. El profe es muy buena persona y lo ayuda si tiene algún problema.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '10d9a4dfb5ae4986844019f3d0c4b82aef0d19cb54070167a37f1fdfe6252999'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'edfbd36207348d1994ce68f9a727a06415a0c2b2347b780c3d1bfa1502764397'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Muy pura vida! Al principio las clases son cansadas pero después son solo de juegos y actividades que hacen que uno se divierta y se olvide por un rato del semestre'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f9df177856907e5a415fb248a4afe1dfb3dfc9bfaa9bc3d86c8e2a331b2e6af8'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'La mayoría de clases son de hacer un circuito funcional, pero no son tan matadas. Le importa mucho la asistencia, básicamente el curso se pasa con ir a las clases y a los eventos (2 por semestre). El profe es súper buena nota. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2efa38806669759aaf3c239f9fbcaaaceaf5704c1495cffd90e8232a98dd9639'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Buen profe, super buena nota. A veces las clases son un toque cansadas, pero diay, de eso se trata :0'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '9dc3a9c6a807753838c5438da22890d80c2a34f0ee78852a887bcf1f48cacbf7'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Súper buena nota. Al principio las clases son cansadas pero luego son muy relajadas y entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'be21f84908a187ccd8dc67b34151125b4a230a138a9a01c7a5c2ec9184f656a6'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'Excelente profesor, sus clases son muy dinámicas y variadas. Las actividades que planean son muy entretenidas y las clases no son tan matadas como dicen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'fd3dc6683d089b92bab34f34f57252b90c6ba4bdc7ecee0e9edbded2a0a5b7f6'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c89d157511e102a1e8d045db9fa4c7a6b54c82f91e5e53ed8c264a60dc75c0a9'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-19T00:00:00+00:00'::TIMESTAMPTZ, '588c8d829d3b13cc4a4bfa3fef921d912254b407fdce690eed55073d5255bcc6'::TEXT, ARRAY[574]::BIGINT[]),
    (181::BIGINT, 'Demasiado tuanis llevar algo con este profe. Muy buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '51050cc5f45858bf3ce52b0b37969307b8734fd74c0fc21fc1168d75ae12047d'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'La clase es muy buena para empezar con el ejercicio lo que no es muy entretenido (a mi parecer) son las actividades obligatorias extras que son carreras de atletismo y campo traviesa.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f426c53eb3fee33ba81d07c79d369b10b304185ea92863b83e00a01701d38115'::TEXT, ARRAY[494]::BIGINT[]),
    (181::BIGINT, 'El curso con él es súper entretenido y basta solo con ir y si un día no podés, te da la oportunidad de reponerla. Hay días que la clase es súper dura y amanecés que te duele todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c0578312dc08b5b70ae76a362b83140203ef8674127a97483e14d193111683fc'::TEXT, ARRAY[494]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
